//! The wire types: generated by `build.rs` from `docs/protocol.schema.json` and never written by
//! hand. Only `Call`, the one trait the generated calls implement, is here.

use serde::{Serialize, de::DeserializeOwned};

/// A call of the protocol: the params type names its method and the type of its result.
pub trait Call: Serialize {
    const METHOD: &'static str;
    type Output: DeserializeOwned;
}

#[allow(clippy::all, clippy::pedantic, dead_code, unused_imports)]
mod generated {
    use super::Call;
    include!(concat!(env!("OUT_DIR"), "/wire.rs"));
}

pub use generated::*;
